import java.util.Scanner;

public class p1096g {
    static long MOD = 998244353;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        long[] base = new long[10];
        for (int i = 0; i < k; i++) {
            int index = scanner.nextInt();
            base[index] = 1;
        }
        long[] result = fastExponentiation(base, n >> 1);
        long totalSum = 0;
        for (long val : result) {
            totalSum = (totalSum + (val * val) % MOD) % MOD;
        }
        System.out.println(totalSum);
    }

    static long[] fastExponentiation(long[] array, long power) {
        if (power == 1) return array;
        if ((power & 1) != 0) return FFT.multiplyPrecise(array, fastExponentiation(array, power - 1));
        long[] half = fastExponentiation(array, power >> 1);
        return FFT.multiplyPrecise(half, half);
    }

    static class FFT {
        static final int maxk = 21, maxn = (1 << maxk) + 1;
        static double[] wR = new double[maxn], wI = new double[maxn], rR = new double[maxn], rI = new double[maxn], aR = new double[maxn], aI = new double[maxn];
        static int n, k, lastk = -1, dp[] = new int[maxn];

        static void fftTransform(boolean inverse) {
            if (lastk != k) {
                lastk = k; dp[0] = 0;
                for (int i = 1, g = -1; i < n; i++) {
                    if ((i & (i - 1)) == 0) g++;
                    dp[i] = dp[i ^ (1 << g)] ^ (1 << (k - 1 - g));
                }
                wR[1] = 1; wI[1] = 0;
                for (int t = 0; t < k - 1; t++) {
                    double angle = Math.PI / n * (1 << (k - 1 - t));
                    double cosA = Math.cos(angle), sinA = Math.sin(angle);
                    int p2 = (1 << t), p3 = p2 * 2;
                    for (int j = p2, idx = j * 2; j < p3; j++, idx += 2) {
                        wR[idx] = wR[j];
                        wI[idx] = wI[j];
                        wR[idx + 1] = wR[j] * cosA - wI[j] * sinA;
                        wI[idx + 1] = wR[j] * sinA + wI[j] * cosA;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                int d = dp[i];
                if (i < d) {
                    double tmpR = aR[i]; aR[i] = aR[d]; aR[d] = tmpR;
                    double tmpI = aI[i]; aI[i] = aI[d]; aI[d] = tmpI;
                }
            }
            if (inverse) for (int i = 0; i < n; i++) aI[i] = -aI[i];
            for (int len = 1; len < n; len <<= 1) {
                for (int i = 0; i < n; i += len) {
                    int wit = len;
                    for (int j = i, j2 = i + len; j < i + len; j++, j2++) {
                        double tmpR = aR[j2] * wR[wit] - aI[j2] * wI[wit];
                        double tmpI = aR[j2] * wI[wit] + aI[j2] * wR[wit];
                        wit++;
                        aR[j2] = aR[j] - tmpR;
                        aI[j2] = aI[j] - tmpI;
                        aR[j] += tmpR;
                        aI[j] += tmpI;
                    }
                }
            }
        }

        static long[] multiplyPrecise(long[] a, long[] b) {
            long baseVal = (long) Math.sqrt(MOD);
            long[] a1 = new long[a.length], a2 = new long[a.length], b1 = new long[b.length], b2 = new long[b.length];
            for (int i = 0; i < a.length; i++) {
                a1[i] = a[i] % baseVal;
                a2[i] = a[i] / baseVal;
            }
            for (int i = 0; i < b.length; i++) {
                b1[i] = b[i] % baseVal;
                b2[i] = b[i] / baseVal;
            }
            long[] r11 = multiply(a1, b1);
            long[] r12 = multiply(a1, b2);
            long[] r21 = multiply(a2, b1);
            long[] r22 = multiply(a2, b2);
            long[] res = new long[r11.length];
            for (int i = 0; i < res.length; i++) {
                res[i] = (baseVal * baseVal * r22[i] + baseVal * (r12[i] + r21[i]) + r11[i]) % MOD;
            }
            return res;
        }
    }
}
